import random

def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    # Endgame: defect in final few rounds only if opponent is not strongly cooperative.
    if n >= 98:
        if opp_def * 4 <= n:
            return 'C'
        return 'D'

    # Measure recent behavior over a flexible window.
    w = 8 if n >= 8 else n
    recent = opp[-w:]
    recent_def = sum(1 for a in recent if a == 'D')
    recent_c = w - recent_def

    # Reset-aware: if the provided history starts with many CC rounds then
    # opponent defected a few times and returned to C, be tolerant.  Detect
    # a run of C at the tail after a D run.
    tail_c_run = 0
    for a in reversed(opp):
        if a == 'C':
            tail_c_run += 1
        else:
            break

    # Opponent's total defections are very low overall -> cooperate, but
    # probe occasionally if late in match to exploit pure cooperators slightly.
    if opp_def == 0:
        if n >= 85:
            # endgame exploitation of unconditional cooperator
            return 'C' if rng.random() < 0.35 else 'D'
        return 'C'

    # Heavy defector: defect, with rare olive branch only when they've been
    # cooperative for a while.
    if opp_def * 2 > n and recent_def >= 3:
        if tail_c_run >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Strong sustained defection overall.
    if opp_def * 3 >= n * 2:
        if tail_c_run >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Recent heavy defection: retaliate but offer olive branch when they calm.
    if recent_def * 2 >= w and w >= 4:
        if tail_c_run >= 2 and recent_c >= 1:
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Reciprocal core: mirror last opponent move, with generous forgiveness.
    if last_opp == 'D':
        # If opponent has just started defecting after a long cooperative run,
        # punish once but be ready to forgive.
        if opp_def <= 3 and n >= 10:
            if tail_c_run == 0 and rng.random() < 0.2:
                return 'C'
            return 'D'
        # Long mutual defection streak check: if both of us have been defecting,
        # try to break out with C.
        dd_run = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D' and me[i] == 'D':
                dd_run += 1
            else:
                break
        if dd_run >= 2 and rng.random() < 0.4:
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # last_opp == 'C'
    # Reward cooperation; occasionally exploit very cooperative opponent late.
    if opp_def * 4 <= n:
        if n >= 80 and recent_def == 0 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Moderate defector: cooperate but keep an eye on recent pattern.
    if recent_def <= 1:
        return 'C'

    return 'C'
